def _split_segments(segment: str) -> list[str]:
    parts: list[str] = []
    buf: list[str] = []
    depth = 0
    in_s = in_d = esc = False
    i = 0
    while i < len(segment):
        ch = segment[i]
        if esc:
            buf.append(ch)
            esc = False
            i += 1
            continue
        if ch == "\\" and (in_s or in_d):
            buf.append(ch)
            esc = True
            i += 1
            continue
        if not in_d and ch == "'" and not in_s:
            in_s = True
            buf.append(ch)
            i += 1
            continue
        if in_s:
            buf.append(ch)
            if ch == "'":
                in_s = False
            i += 1
            continue
        if not in_s and ch == '"' and not in_d:
            in_d = True
            buf.append(ch)
            i += 1
            continue
        if in_d:
            buf.append(ch)
            if ch == '"':
                in_d = False
            i += 1
            continue
        if ch == "(":
            depth += 1
        elif ch == ")" and depth > 0:
            depth -= 1
        if depth > 0:
            buf.append(ch)
            i += 1
            continue
        two = segment[i : i + 2]
        if two in {"&&", "||"}:
            value = "".join(buf)
            if value:
                parts.append(value)
            buf = []
            i += 2
            continue
        if ch in {"|", ";"}:
            value = "".join(buf)
            if value:
                parts.append(value)
            buf = []
            i += 1
            continue
        buf.append(ch)
        i += 1
    value = "".join(buf)
    if value:
        parts.append(value)
    return parts


def _has_command_substitution(seg: str) -> bool:
    i = 0
    while True:
        idx = seg.find("$(", i)
        if idx < 0:
            return False
        if not seg.startswith("$((", idx):
            return True
        i = idx + 2


def _tokenize(seg: str) -> list[str]:
    toks: list[str] = []
    cur: list[str] = []
    in_s = in_d = esc = False
    for ch in seg:
        if esc:
            cur.append(ch)
            esc = False
            continue
        if ch == "\\" and (in_s or in_d):
            cur.append(ch)
            esc = True
            continue
        if not in_d and ch == "'" and not in_s:
            in_s = True
            cur.append(ch)
            continue
        if in_s:
            cur.append(ch)
            if ch == "'":
                in_s = False
            continue
        if not in_s and ch == '"' and not in_d:
            in_d = True
            cur.append(ch)
            continue
        if in_d:
            cur.append(ch)
            if ch == '"':
                in_d = False
            continue
        if ch.isspace():
            if cur:
                toks.append("".join(cur))
                cur = []
            continue
        cur.append(ch)
    if cur:
        toks.append("".join(cur))
    return toks


def _normalize_token(token: str, repo_root: Path, plugin_root: Path) -> str:
    value = token.strip()
    if len(value) >= 2 and ((value[0] == value[-1] == "'") or (value[0] == value[-1] == '"')):
        value = value[1:-1]
    value = value.replace("${CLAUDE_PLUGIN_ROOT}/", "").replace("$CLAUDE_PLUGIN_ROOT/", "")
    for root in (plugin_root, repo_root):
        prefix = str(root).rstrip("/") + "/"
        value = value.removeprefix(prefix)
    return value.strip()


def _parse_command_segment(
    rows: list[PlanCommandRow],
    source_line: int,
    seg: str,
    repo_root: Path,
    plugin_root: Path,
    uid_next: list[int],
) -> None:
    if _has_command_substitution(seg):
        _emit_parse_note(rows, source_line, "subshell")
        return
    if "<(" in seg:
        _emit_parse_note(rows, source_line, "process_substitution")
        return
    if re.search(r"(^|\s)eval(\s|$)", seg):
        _emit_parse_note(rows, source_line, "eval")
        return
    toks = _tokenize(seg)
    while toks:
        first = _normalize_token(toks[0], repo_root, plugin_root)
        if first in {"bash", "sh", "dash", "/bin/bash", "/bin/sh", "env"}:
            toks.pop(0)
            continue
        if first == "-c":
            _emit_parse_note(rows, source_line, "inline-shell")
            return
        if first == "--":
            toks.pop(0)
            continue
        if re.match(r"^[A-Za-z_][A-Za-z0-9_]*=", first):
            toks.pop(0)
            continue
        break
    if not toks:
        return
    script = _normalize_token(toks[0], repo_root, plugin_root)
    if not script or script.startswith("-"):
        return
    if ".." in script or script.startswith("/"):
        _emit_parse_note(rows, source_line, "non-canonical-script-path")
        return
    if _bad_field(script):
        _emit_parse_note(rows, source_line, "charset-violation")
        return
    uid_next[0] += 1
    uid = str(uid_next[0])
    flags = 0
    k = 1
    while k < len(toks):
        tok = _normalize_token(toks[k], repo_root, plugin_root)
        if not tok:
            k += 1
            continue
        if not tok.startswith("--"):
            k += 1
            continue
        if tok == "--":
            break
        body = tok[2:]
        if not body:
            k += 1
            continue
        if "=" in body:
            flag, value = body.split("=", 1)
        else:
            flag = body
            value = ""
            if k + 1 < len(toks):
                nxt = _normalize_token(toks[k + 1], repo_root, plugin_root)
                if nxt and not nxt.startswith("-"):
                    value = nxt
                    k += 1
        if _bad_field(flag) or _bad_field(value):
            _emit_parse_note(rows, source_line, "charset-violation")
            return
        rows.append(PlanCommandRow("invocation", source_line, script_path=script, flag=flag, flag_value=value, cmd_uid=uid))
        flags += 1
        k += 1
    if flags == 0:
        rows.append(PlanCommandRow("invocation_no_flags", source_line, script_path=script, cmd_uid=uid))


def parse_plan_commands(plan_text: str, repo_root: str | Path | None = None, plugin_root: str | Path | None = None) -> list[PlanCommandRow]:
    repo = Path(repo_root).resolve() if repo_root else _repo_root_from()
    plugin = Path(plugin_root).resolve() if plugin_root else _plugin_root(repo)
    rows: list[PlanCommandRow] = []
    lines = plan_text.splitlines()
    files_section = ""
    pending_updated = ""
    in_fence = False
    fence_start = 0
    fence_buf: list[str] = []
    uid_next = [0]

    def process_fence(start: int, text: str) -> None:
        if not text:
            return
        joined = _join_continuations(text)
        phys = joined.split("\n")
        for line_no, piece in _strip_heredoc_multiline(phys, start, rows):
            if not piece:
                continue
            for seg in _split_segments(piece):
                seg = seg.strip()
                if seg:
                    _parse_command_segment(rows, line_no, seg, repo, plugin, uid_next)

    for idx, raw in enumerate(lines, start=1):
        if re.match(r"^###[ \t]+Files[ \t]+to[ \t]+create([ \t]|$)", raw):
            files_section = "create"
            pending_updated = ""
            continue
        if re.match(r"^###[ \t]+Files[ \t]+to[ \t]+update([ \t]|$)", raw):
            files_section = "update"
            pending_updated = ""
            continue
        h3_misc = bool(re.match(r"^###[ \t]+", raw)) and not raw.startswith("####") and not re.match(r"^###[ \t]+Files[ \t]+to[ \t]+(create|update)", raw)
        h2_misc = bool(re.match(r"^##[ \t]+", raw)) and not raw.startswith("###") and not re.match(r"^##[ \t]+Files[ \t]+to[ \t]+(create|update)", raw)
        if h3_misc or h2_misc:
            br_new = bool(re.match(r"^#{2,3}[ \t]+NEW[ \t]+\[", raw))
            br_upd = bool(re.match(r"^#{2,3}[ \t]+UPDATED[ \t]+\[", raw))
            if re.match(r"^#{2,3}[ \t]+NEW:", raw) or br_new:
                _emit_new_script(rows, _bracket_heading_path(raw) if br_new else _heading_path(raw), idx)
            if re.match(r"^#{2,3}[ \t]+UPDATED:", raw) or br_upd:
                pending_updated = _bracket_heading_path(raw) if br_upd else _heading_path(raw)
            elif re.match(r"^#{2,3}[ \t]+", raw):
                pending_updated = ""
            if not (re.match(r"^#{2,3}[ \t]+(NEW:|UPDATED:)", raw) or br_new or br_upd):
                files_section = ""
            continue
        if pending_updated and re.match(r"^[ \t]*-[ \t]+Adds[ \t]+flag:", raw):
            flag = re.sub(r"^[ \t]*-[ \t]+Adds[ \t]+flag:[ \t]*", "", raw).strip()
            _emit_updated_flag(rows, pending_updated, flag, idx)
            continue
        if files_section == "create" and "**NEW**:" in raw:
            path = re.sub(r"^[^*]*\*\*NEW\*\*:[ \t]*", "", raw).strip()
            _emit_new_script(rows, path, idx)
        if files_section == "update" and "**UPDATED**:" in raw:
            pending_updated = _strip_md_ticks(re.sub(r"^[^*]*\*\*UPDATED\*\*:[ \t]*", "", raw).strip())
            continue
        if files_section == "update" and pending_updated and re.match(r"^[ \t]+-[ \t]+Adds[ \t]+flag:", raw):
            flag = re.sub(r"^[ \t]+-[ \t]+Adds[ \t]+flag:[ \t]*", "", raw).strip()
            _emit_updated_flag(rows, pending_updated, flag, idx)

        if re.match(r"^```[ \t]*(bash|sh)[ \t]*$", raw):
            in_fence = True
            fence_start = idx
            fence_buf = []
            continue
        if in_fence and re.match(r"^```[ \t]*$", raw):
            process_fence(fence_start, "\n".join(fence_buf))
            in_fence = False
            fence_start = 0
            fence_buf = []
            continue
        if in_fence:
            fence_buf.append(raw)
    if in_fence and fence_buf:
        process_fence(fence_start, "\n".join(fence_buf))
    return rows


def render_plan_command_tsv(rows: Iterable[PlanCommandRow]) -> str:
    return HEADER + "\n" + "\n".join(row.to_tsv() for row in rows) + "\n"


def parse_plan_commands_main(argv: list[str]) -> int:
    quiet_init(argv0="plan parse-commands")
    parser = argparse.ArgumentParser(prog="cli.py plan parse-commands")
    parser.add_argument("--plan-file", required=True)
    parser.add_argument("--output", required=True)
    parser.add_argument("--repo-root")
    args = parser.parse_args(argv)
    plan = Path(args.plan_file)
    if not plan.is_file():
        diagnostic(f"parse-commands: plan file missing or unreadable: {plan}")
        return 2
    repo = _repo_root_for_plan(plan, args.repo_root)
    rows = parse_plan_commands(plan.read_text(encoding="utf-8", errors="replace"), repo, _plugin_root(repo))
    _atomic_write(Path(args.output), render_plan_command_tsv(rows))
    return 0


